#include "darc.h"
#include <stdlib.h>
#include <string.h>
#include <limits.h>

typedef struct HNode { uint64_t w; int sym,minsym,leaf; struct HNode*l,*r; } HNode;
static int tokpush(DarcTokVec*v,DarcLzTok t){if(v->n==v->cap){size_t nc=v->cap?v->cap*2:64;DarcLzTok*p=darc_realloc(v->v,nc*sizeof*p);if(!p)return -1;v->v=p;v->cap=nc;}v->v[v->n++]=t;return 0;}
void darc_tokvec_free(DarcTokVec*v){free(v->v);memset(v,0,sizeof *v);}

int darc_lz77_tokenize(const uint8_t*in,size_t n,DarcTokVec*out){memset(out,0,sizeof *out);if(!n)return 0;int *head=darc_malloc(65536*sizeof *head);int *prev=darc_malloc((n?n:1)*sizeof *prev);if(!head||!prev){free(head);free(prev);return -1;}for(int i=0;i<65536;i++)head[i]=-1;for(size_t i=0;i<n;i++)prev[i]=-1;size_t i=0;while(i<n){size_t best=0;uint16_t bestd=0;if(i+2<n){unsigned hv=(unsigned)(((unsigned)in[i]*251u+(unsigned)in[i+1]*31u+in[i+2])&65535u);int p=head[hv];while(p>=0){size_t pp=(size_t)p;if(i-pp>32768){p=prev[pp];continue;}size_t dist=i-pp,ml=0,max=n-i;if(max>258)max=258;while(ml<max){size_t src=i+ml-dist;uint8_t sb=src<i?in[src]:in[i+(ml-dist)]; /* overlap is equivalent to prior emitted sequence; input itself must match */ (void)sb;if(in[i+ml]!=in[i+ml-dist])break;ml++;}if(ml>=3&&(ml>best||(ml==best&&dist<bestd))){best=ml;bestd=(uint16_t)dist;if(best==258)break;}p=prev[pp];}}
      if(best>=3){DarcLzTok t={1,0,bestd,(uint16_t)best};if(tokpush(out,t))goto fail;for(size_t k=0;k<best;k++){size_t pos=i+k;if(pos+2<n){unsigned hv=(unsigned)(((unsigned)in[pos]*251u+(unsigned)in[pos+1]*31u+in[pos+2])&65535u);prev[pos]=head[hv];head[hv]=(int)pos;}}i+=best;}else{DarcLzTok t={0,in[i],0,0};if(tokpush(out,t))goto fail;if(i+2<n){unsigned hv=(unsigned)(((unsigned)in[i]*251u+(unsigned)in[i+1]*31u+in[i+2])&65535u);prev[i]=head[hv];head[hv]=(int)i;}i++;}}
 free(head);free(prev);return 0;fail:free(head);free(prev);darc_tokvec_free(out);return -1;}
int darc_lz77_serialize(const DarcTokVec*t,DarcBuf*out){darc_buf_init(out);for(size_t i=0;i<t->n;i++){if(t->v[i].kind==0){if(darc_buf_u8(out,0)||darc_buf_u8(out,t->v[i].lit))goto fail;}else{if(t->v[i].dist<1||t->v[i].dist>32768||t->v[i].len<3||t->v[i].len>258)goto fail;if(darc_buf_u8(out,1)||darc_buf_u16(out,t->v[i].dist)||darc_buf_u16(out,t->v[i].len))goto fail;}}return 0;fail:darc_buf_free(out);return -1;}
static int hcmp(const HNode*a,const HNode*b){if(a->w!=b->w)return a->w<b->w?-1:1;if(a->minsym!=b->minsym)return a->minsym<b->minsym?-1:1;if(a->leaf!=b->leaf)return a->leaf? -1:1;return 0;}
static HNode*popmin(HNode**a,size_t*n){size_t bi=0;for(size_t i=1;i<*n;i++)if(hcmp(a[i],a[bi])<0)bi=i;HNode*r=a[bi];a[bi]=a[--*n];return r;}
static void lens_rec(HNode*n,int d,uint8_t lens[256]){if(n->leaf){lens[n->sym]=(uint8_t)(d?d:1);return;}lens_rec(n->l,d+1,lens);lens_rec(n->r,d+1,lens);}
int darc_huff_lengths(const uint8_t*in,size_t n,uint8_t lens[256]){memset(lens,0,256);uint64_t f[256]={0};for(size_t i=0;i<n;i++)f[in[i]]++;HNode nodes[511],*q[511];size_t nn=0,qn=0;for(int s=0;s<256;s++)if(f[s]){nodes[nn]=(HNode){f[s],s,s,1,NULL,NULL};q[qn++]=&nodes[nn++];}if(!qn)return 0;if(qn==1){lens[q[0]->sym]=1;return 0;}while(qn>1){HNode*a=popmin(q,&qn),*b=popmin(q,&qn);nodes[nn]=(HNode){a->w+b->w,-1,a->minsym<b->minsym?a->minsym:b->minsym,0,a,b};q[qn++]=&nodes[nn++];}lens_rec(q[0],0,lens);return 0;}
typedef struct { uint32_t code; uint8_t len; } HCode;
static int codes_from_lens(const uint8_t lens[256],HCode c[256]){memset(c,0,256*sizeof*c);unsigned count[33]={0},max=0;for(int s=0;s<256;s++){if(lens[s]>32)return -1;if(lens[s]){count[lens[s]]++;if(lens[s]>max)max=lens[s];}}if(!max)return 0;int64_t left=1;for(unsigned l=1;l<=max;l++){left=left*2-(int64_t)count[l];if(left<0)return -1;}uint32_t next[33]={0},code=0;for(unsigned l=1;l<=max;l++){code=(code+count[l-1])<<1;next[l]=code;}for(unsigned l=1;l<=max;l++)for(int s=0;s<256;s++)if(lens[s]==l){c[s].len=(uint8_t)l;c[s].code=next[l]++;}return 0;}
int darc_huff_encode(const uint8_t*in,size_t n,const uint8_t lens[256],DarcBuf*out){darc_buf_init(out);HCode c[256];if(codes_from_lens(lens,c))return -1;uint8_t cur=0;int used=0;for(size_t i=0;i<n;i++){HCode x=c[in[i]];if(!x.len){darc_buf_free(out);return -1;}for(int b=x.len-1;b>=0;b--){cur=(uint8_t)((cur<<1)|((x.code>>b)&1u));used++;if(used==8){if(darc_buf_u8(out,cur)){darc_buf_free(out);return -1;}cur=0;used=0;}}}if(used){cur<<=(8-used);if(darc_buf_u8(out,cur)){darc_buf_free(out);return -1;}}return 0;}
int darc_huff_decode(const uint8_t*bits,size_t bn,const uint8_t lens[256],size_t outn,DarcBuf*out){darc_buf_init(out);HCode c[256];if(codes_from_lens(lens,c))return -1;if(!outn)return 0;if(darc_buf_reserve(out,outn))return -1;uint32_t code=0;unsigned len=0;size_t bitpos=0;while(out->len<outn){if(bitpos>=bn*8){darc_buf_free(out);return -1;}uint8_t bit=(uint8_t)((bits[bitpos/8]>>(7-(bitpos%8)))&1);bitpos++;code=(code<<1)|bit;len++;if(len>32){darc_buf_free(out);return -1;}int found=-1;for(int s=0;s<256;s++)if(c[s].len==len&&c[s].code==code){found=s;break;}if(found>=0){out->data[out->len++]=(uint8_t)found;code=0;len=0;}}return 0;}
int darc_lzh1_compress(const uint8_t*in,size_t n,DarcBuf*out){DarcTokVec t;DarcBuf tok,bits;uint8_t lens[256];if(darc_lz77_tokenize(in,n,&t))return -1;if(darc_lz77_serialize(&t,&tok)){darc_tokvec_free(&t);return -1;}darc_tokvec_free(&t);if(darc_huff_lengths(tok.data,tok.len,lens)||darc_huff_encode(tok.data,tok.len,lens,&bits)){darc_buf_free(&tok);return -1;}darc_buf_init(out);if(darc_buf_put(out,"LZH1",4)||darc_buf_u64(out,(uint64_t)tok.len)||darc_buf_put(out,lens,256)||darc_buf_u64(out,(uint64_t)bits.len)||darc_buf_put(out,bits.data,bits.len)){darc_buf_free(out);darc_buf_free(&tok);darc_buf_free(&bits);return -1;}darc_buf_free(&tok);darc_buf_free(&bits);return 0;}
int darc_lzh1_decompress(const uint8_t*in,size_t n,size_t expected,DarcBuf*out){if(n<276||memcmp(in,"LZH1",4))return -1;uint64_t tl=darc_rd_u64(in+4),bl=darc_rd_u64(in+268);if(tl>SIZE_MAX||bl>SIZE_MAX||276u+(size_t)bl!=n)return -1;DarcBuf tok;if(darc_huff_decode(in+276,(size_t)bl,in+12,(size_t)tl,&tok))return -1;darc_buf_init(out);if(darc_buf_reserve(out,expected)){darc_buf_free(&tok);return -1;}size_t p=0;while(p<tok.len){uint8_t k=tok.data[p++];if(k==0){if(p>=tok.len||out->len>=expected)goto bad;out->data[out->len++]=tok.data[p++];}else if(k==1){if(tok.len-p<4)goto bad;uint16_t d=darc_rd_u16(tok.data+p),l=darc_rd_u16(tok.data+p+2);p+=4;if(d<1||d>32768||l<3||l>258||d>out->len||l>expected-out->len)goto bad;for(uint16_t j=0;j<l;j++){out->data[out->len]=out->data[out->len-d];out->len++;}}else goto bad;}darc_buf_free(&tok);if(out->len!=expected){darc_buf_free(out);return -1;}return 0;bad:darc_buf_free(&tok);darc_buf_free(out);return -1;}
